import{_ as o,c as i,o as l,b2 as a}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"异常体系模块设计（quickboot-common/common/exception）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-09-exception-system-design.md","filePath":"superpowers/specs/2026-05-09-exception-system-design.md"}'),c={name:"superpowers/specs/2026-05-09-exception-system-design.md"};function d(r,e,t,n,s,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="异常体系模块设计-quickboot-common-common-exception" tabindex="-1">异常体系模块设计（quickboot-common/common/exception） <a class="header-anchor vp-link" href="#异常体系模块设计-quickboot-common-common-exception" aria-label="Permalink to &quot;异常体系模块设计（quickboot-common/common/exception）&quot;">​</a></h1><h2 id="_1-目标与范围" tabindex="-1">1. 目标与范围 <a class="header-anchor vp-link" href="#_1-目标与范围" aria-label="Permalink to &quot;1. 目标与范围&quot;">​</a></h2><h3 id="_1-1-目标" tabindex="-1">1.1 目标 <a class="header-anchor vp-link" href="#_1-1-目标" aria-label="Permalink to &quot;1.1 目标&quot;">​</a></h3><p>本设计用于在项目内建立统一异常体系，确保：</p><ul><li>业务侧抛出异常语义一致（区分可预期与严重错误）。</li><li>客户端响应格式一致（<code>R&lt;Void&gt;</code> + 稳定业务码）。</li><li>服务端可观测性完整（日志、<code>traceId</code>、异常分类）。</li><li>错误消息具备国际化能力（基于错误码解析）。</li></ul><h3 id="_1-2-范围" tabindex="-1">1.2 范围 <a class="header-anchor vp-link" href="#_1-2-范围" aria-label="Permalink to &quot;1.2 范围&quot;">​</a></h3><ul><li>本次只覆盖异常模型、错误码规范、全局异常映射机制。</li><li>不覆盖具体业务模块的异常抛出改造细节。</li><li>不改变既有统一响应对象 <code>R</code> 与 i18n 基础设施 <code>I18nUtil</code> 的既有契约。</li></ul><h3 id="_1-3-分层边界" tabindex="-1">1.3 分层边界 <a class="header-anchor vp-link" href="#_1-3-分层边界" aria-label="Permalink to &quot;1.3 分层边界&quot;">​</a></h3><ul><li><code>quickboot-common</code>：仅提供异常能力（异常基类、子类、错误码常量、可选辅助工具）。</li><li><code>quickboot-web</code>（或应用模块）：提供 <code>@RestControllerAdvice</code>，负责 HTTP 状态与 <code>R</code> 响应组装。</li></ul><h2 id="_2-设计原则" tabindex="-1">2. 设计原则 <a class="header-anchor vp-link" href="#_2-设计原则" aria-label="Permalink to &quot;2. 设计原则&quot;">​</a></h2><ul><li>语义优先：异常类型表达意图，避免散落式 <code>try/catch</code>。</li><li>兼容优先：复用现有 <code>R</code>、<code>I18nUtil</code>、<code>traceId</code> 机制。</li><li>安全优先：客户端不暴露内部堆栈与敏感细节。</li><li>扩展优先：错误码分段清晰，映射表可按异常类型扩展。</li></ul><h2 id="_3-核心模型设计" tabindex="-1">3. 核心模型设计 <a class="header-anchor vp-link" href="#_3-核心模型设计" aria-label="Permalink to &quot;3. 核心模型设计&quot;">​</a></h2><h3 id="_3-1-baseexception" tabindex="-1">3.1 BaseException <a class="header-anchor vp-link" href="#_3-1-baseexception" aria-label="Permalink to &quot;3.1 BaseException&quot;">​</a></h3><p><code>BaseException extends RuntimeException</code></p><p>字段约定：</p><ul><li><code>Integer code</code>：业务错误码。</li><li><code>String msg</code>：默认文案（i18n 未命中时回退）。</li><li><code>Object[] args</code>：i18n 占位参数。</li></ul><p>构造器最小集合：</p><ul><li><code>(Integer code, String msg)</code></li><li><code>(Integer code, String msg, Object[] args)</code></li><li><code>(Integer code, String msg, Throwable cause)</code></li><li><code>(Integer code, String msg, Object[] args, Throwable cause)</code></li></ul><p>约束：</p><ul><li><code>code</code> 不能为空；为空时在构造阶段降级为内部错误码。</li><li><code>msg</code> 允许为空，但最终响应阶段必须有兜底文案。</li></ul><h3 id="_3-2-warningexception" tabindex="-1">3.2 WarningException <a class="header-anchor vp-link" href="#_3-2-warningexception" aria-label="Permalink to &quot;3.2 WarningException&quot;">​</a></h3><p><code>WarningException extends BaseException</code></p><p>语义：</p><ul><li>表示可预期异常（业务校验失败、权限拒绝、认证失败、限流、幂等冲突、来源拦截等）。</li><li>默认映射 4xx/429（由映射表决定）。</li></ul><h3 id="_3-3-errorexception" tabindex="-1">3.3 ErrorException <a class="header-anchor vp-link" href="#_3-3-errorexception" aria-label="Permalink to &quot;3.3 ErrorException&quot;">​</a></h3><p><code>ErrorException extends BaseException</code></p><p>语义：</p><ul><li>表示严重错误（系统内部故障、关键依赖失败）。</li><li>默认映射 <code>HTTP 500</code>，建议使用 <code>4xxxx</code> 业务码。</li></ul><h2 id="_4-错误码规范" tabindex="-1">4. 错误码规范 <a class="header-anchor vp-link" href="#_4-错误码规范" aria-label="Permalink to &quot;4. 错误码规范&quot;">​</a></h2><h3 id="_4-1-分段规则" tabindex="-1">4.1 分段规则 <a class="header-anchor vp-link" href="#_4-1-分段规则" aria-label="Permalink to &quot;4.1 分段规则&quot;">​</a></h3><ul><li><code>1xxxx</code>：通用错误</li><li><code>2xxxx</code>：业务错误</li><li><code>3xxxx</code>：安全相关错误</li><li><code>4xxxx</code>：系统错误</li></ul><h3 id="_4-2-组织形式" tabindex="-1">4.2 组织形式 <a class="header-anchor vp-link" href="#_4-2-组织形式" aria-label="Permalink to &quot;4.2 组织形式&quot;">​</a></h3><p>采用“单一总类 + 内部分组常量”模式，例如：</p><ul><li><code>ErrorCodes.Common</code></li><li><code>ErrorCodes.Biz</code></li><li><code>ErrorCodes.Security</code></li><li><code>ErrorCodes.System</code></li></ul><h3 id="_4-3-最小常量集-首批" tabindex="-1">4.3 最小常量集（首批） <a class="header-anchor vp-link" href="#_4-3-最小常量集-首批" aria-label="Permalink to &quot;4.3 最小常量集（首批）&quot;">​</a></h3><ul><li>通用：参数非法、请求格式错误。</li><li>业务：状态不允许、幂等重复。</li><li>安全：认证失败、权限不足、来源拦截、限流。</li><li>系统：内部错误、关键依赖不可用。</li></ul><blockquote><p>注：具体数值在实现阶段与现有代码库占用情况对齐，避免冲突。</p></blockquote><h2 id="_5-全局异常处理设计" tabindex="-1">5. 全局异常处理设计 <a class="header-anchor vp-link" href="#_5-全局异常处理设计" aria-label="Permalink to &quot;5. 全局异常处理设计&quot;">​</a></h2><h3 id="_5-1-处理职责" tabindex="-1">5.1 处理职责 <a class="header-anchor vp-link" href="#_5-1-处理职责" aria-label="Permalink to &quot;5.1 处理职责&quot;">​</a></h3><p>全局异常处理器放在 <code>quickboot-web</code>（或应用模块），职责包括：</p><ul><li>异常分类识别。</li><li>消息国际化解析与回退。</li><li>HTTP 状态确定。</li><li>统一响应 <code>R.error(code, message)</code> 输出。</li><li>结构化日志记录。</li></ul><h3 id="_5-2-消息解析规则" tabindex="-1">5.2 消息解析规则 <a class="header-anchor vp-link" href="#_5-2-消息解析规则" aria-label="Permalink to &quot;5.2 消息解析规则&quot;">​</a></h3><p>对 <code>BaseException</code> 派生异常：</p><ol><li>使用 <code>String.valueOf(code)</code> 作为 i18n key。</li><li>先尝试 <code>I18nUtil.getMessage(codeKey, args, msg)</code>。</li><li>若未命中且 <code>msg</code> 为空，回退统一兜底文案（如“系统繁忙，请稍后再试”）。</li></ol><h3 id="_5-3-http-状态映射规则" tabindex="-1">5.3 HTTP 状态映射规则 <a class="header-anchor vp-link" href="#_5-3-http-状态映射规则" aria-label="Permalink to &quot;5.3 HTTP 状态映射规则&quot;">​</a></h3><p>采用“异常类型 -&gt; HTTP 状态 + 默认业务码”映射表。</p><p>推荐默认映射：</p><ul><li><code>WarningException</code>：默认 <code>400</code>。</li><li>认证失败类：<code>401</code>。</li><li>权限拒绝类：<code>403</code>。</li><li>限流/频控类：<code>429</code>。</li><li><code>ErrorException</code>：<code>500</code>。</li><li>其他未捕获 <code>Throwable</code>：<code>500</code> + 内部错误码。</li></ul><p>说明：</p><ul><li>若异常实例已携带明确业务码，则优先使用异常中的 <code>code</code>。</li><li>未携带业务码时按映射表默认业务码兜底。</li></ul><h3 id="_5-4-响应契约" tabindex="-1">5.4 响应契约 <a class="header-anchor vp-link" href="#_5-4-响应契约" aria-label="Permalink to &quot;5.4 响应契约&quot;">​</a></h3><ul><li>响应体统一为 <code>R&lt;Void&gt;</code>。</li><li>失败响应统一 <code>R.error(code, message)</code>。</li><li><code>traceId</code> 按现有 MDC 机制透出，便于客户端报障与服务端日志关联。</li></ul><h2 id="_6-日志与安全策略" tabindex="-1">6. 日志与安全策略 <a class="header-anchor vp-link" href="#_6-日志与安全策略" aria-label="Permalink to &quot;6. 日志与安全策略&quot;">​</a></h2><ul><li><code>WarningException</code> 记录 <code>warn</code> 级别日志。</li><li><code>ErrorException</code> 与未捕获异常记录 <code>error</code> 级别日志并保留完整堆栈。</li><li>客户端响应禁止返回堆栈、SQL、密钥、内部路径等敏感内容。</li><li>同一错误码在多语言下应表达同一语义，避免跨语言语义漂移。</li></ul><h2 id="_7-数据流-请求到响应" tabindex="-1">7. 数据流（请求到响应） <a class="header-anchor vp-link" href="#_7-数据流-请求到响应" aria-label="Permalink to &quot;7. 数据流（请求到响应）&quot;">​</a></h2><ol><li>Controller/Service 抛出 <code>WarningException</code> 或 <code>ErrorException</code>。</li><li>全局异常处理器捕获并提取 <code>code/msg/args</code>。</li><li>根据 <code>code</code> 调用 i18n 解析 message。</li><li>根据异常类型映射 HTTP 状态。</li><li>返回 <code>R.error(code, message)</code>，附带 <code>traceId</code>。</li><li>服务端记录结构化日志（含异常类别、错误码、traceId、堆栈）。</li></ol><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><h3 id="_8-1-核心用例" tabindex="-1">8.1 核心用例 <a class="header-anchor vp-link" href="#_8-1-核心用例" aria-label="Permalink to &quot;8.1 核心用例&quot;">​</a></h3><ul><li>抛出 <code>WarningException(code=2xxxx)</code>：返回 <code>R.error(2xxxx, message)</code>，message 可命中 i18n。</li><li>i18n 未命中：回退 <code>msg</code>；<code>msg</code> 为空再回退统一兜底文案。</li><li>抛出 <code>ErrorException(4xxxx)</code>：返回 <code>HTTP 500 + R.error(4xxxx, message)</code>。</li><li>抛出未捕获 <code>RuntimeException</code>：返回 <code>HTTP 500 + 内部错误码</code>，不泄露堆栈。</li><li>安全拦截异常：正确映射 401/403/429。</li><li>响应含 <code>traceId</code>，可在日志中检索到同值链路。</li></ul><h3 id="_8-2-回归关注" tabindex="-1">8.2 回归关注 <a class="header-anchor vp-link" href="#_8-2-回归关注" aria-label="Permalink to &quot;8.2 回归关注&quot;">​</a></h3><ul><li>不影响既有 <code>R</code> 成功响应结构。</li><li>不改变现有 i18n 基础能力与 key 约定。</li><li>不引入对业务层无感知的 breaking change。</li></ul><h2 id="_9-实施清单-非代码" tabindex="-1">9. 实施清单（非代码） <a class="header-anchor vp-link" href="#_9-实施清单-非代码" aria-label="Permalink to &quot;9. 实施清单（非代码）&quot;">​</a></h2><ul><li>在 <code>quickboot-common</code> 新增异常模型与错误码常量。</li><li>在 <code>quickboot-web</code> 新增/调整全局异常处理器与映射表。</li><li>补充 <code>i18n/messages*.properties</code> 对应错误码文案。</li><li>增加异常处理测试样例（单元/集成按现有测试基线选择）。</li></ul><h2 id="_10-风险与决策" tabindex="-1">10. 风险与决策 <a class="header-anchor vp-link" href="#_10-风险与决策" aria-label="Permalink to &quot;10. 风险与决策&quot;">​</a></h2><ul><li><p>风险：历史业务异常抛出不规范导致映射不一致。</p></li><li><p>应对：先兼容兜底，再逐步替换为 <code>BaseException</code> 派生异常。</p></li><li><p>风险：错误码冲突。</p></li><li><p>应对：实现前扫描现存错误码，建立保留区段。</p></li><li><p>风险：多语言文案缺失。</p></li><li><p>应对：在测试与发布检查中加入 i18n key 完整性校验。</p></li></ul><h2 id="_11-结论" tabindex="-1">11. 结论 <a class="header-anchor vp-link" href="#_11-结论" aria-label="Permalink to &quot;11. 结论&quot;">​</a></h2><p>本设计采用“<code>common</code> 提供异常能力、<code>web</code> 提供全局处理”的分层方案，满足统一响应、国际化、HTTP 语义与安全可观测要求，并可在不破坏现有契约前提下渐进落地。</p>',67)])])}const x=o(c,[["render",d]]);export{u as __pageData,x as default};
